import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  describe('list_sessions', () => {
    it('accepts a valid list_sessions frame without limit or before', () => {
      const result = validateMessage({type: 'list_sessions'});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
    });

    it('accepts a limit between 1 and 200', () => {
      const result = validateMessage({type: 'list_sessions', limit: 10});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions', limit: 10}});
    });

    it('rejects a limit less than 1 or greater than 200 or not an integer', () => {
      expect(validateMessage({type: 'list_sessions', limit: 0}).valid).toBe(false);
      expect(validateMessage({type: 'list_sessions', limit: 201}).valid).toBe(false);
      expect(validateMessage({type: 'list_sessions', limit: 1.5}).valid).toBe(false);
      expect(validateMessage({type: 'list_sessions', limit: '10'}).valid).toBe(false);
    });

    it('accepts a valid before cursor', () => {
      const result = validateMessage({
        type: 'list_sessions',
        before: {sessionId: 's1', updatedAt: '2023-01-01T00:00:00.000Z'},
      });
      expect(result).toEqual({
        valid: true,
        data: {
          type: 'list_sessions',
          before: {sessionId: 's1', updatedAt: '2023-01-01T00:00:00.000Z'},
        },
      });
    });

    it('rejects an invalid before cursor', () => {
      expect(validateMessage({type: 'list_sessions', before: {sessionId: 's1'}}).valid).toBe(false);
      expect(validateMessage({type: 'list_sessions', before: {sessionId: 's1', updatedAt: 'not a date'}}).valid).toBe(
        false
      );
      expect(
        validateMessage({
          type: 'list_sessions',
          before: {sessionId: '', updatedAt: '2023-01-01T00:00:00.000Z'},
        }).valid
      ).toBe(false);
      expect(
        validateMessage({
          type: 'list_sessions',
          before: {
            sessionId: 'a'.repeat(129),
            updatedAt: '2023-01-01T00:00:00.000Z',
          },
        }).valid
      ).toBe(false);
    });

    it('drops any unknown field like userId', () => {
      const result = validateMessage({type: 'list_sessions', userId: 'user1'});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
    });
  });

  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });
});

